export const TABLES=['table','roundTable','longTable','smallTable','groupTable','booth','highTable','armchair','sofa','bench','windowCounter'];
export const isTable=o=>TABLES.includes(o.type);
export const walkable=o=>!['rug','poster','wallDecor','outlet','light','path','order','pickup','nookArea'].includes(o.type);
export const atmosphereDefaults={lighting:'warm',brightness:80,music:'off',volume:28,ambience:'quiet',scent:'none',speaker:false,diffuser:false};
export function defaultState(){return {version:2,openingVersion:1,studyWingVersion:1,openingRepairBudget:0,money:1500,clean:true,waste:false,floor:false,paint:false,objects:[],lights:[{type:'light',x:-2.4,z:-1.4,upgraded:false},{type:'light',x:2.4,z:-.8,upgraded:false},{type:'light',x:0,z:3.6,upgraded:false}],atmosphere:{...atmosphereDefaults},opened:false}}
export function migrateState(saved){let s=defaultState();if(!saved||!Number.isFinite(saved.money)||!Array.isArray(saved.objects))return s;Object.assign(s,saved);s.atmosphere={...atmosphereDefaults,...saved.atmosphere};s.objects=s.objects.filter(o=>CATALOG[o.type]&&Number.isFinite(o.x)&&Number.isFinite(o.z));s.lights=(s.lights||defaultState().lights).map(l=>Number.isFinite(l.z)?l:{type:'light',x:(400+(l.x-400)/820*860-800)/96,z:(230+(l.y-75)/155*520-510)/50,upgraded:!!l.upgraded});s.version=2;return s}
